import json
import math
from pathlib import Path


def load_payload(path):
    """Read a JSON file whose top-level value is an object or an array."""
    path = Path(path)
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid JSON in {path}") from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level JSON must be an object or array")
    return data


def write_json(path, data):
    """Write normalized JSON with exactly one trailing newline."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(data, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n"
    path.write_text(text, encoding="utf-8")


def build_component(root, contract_path):
    root = Path(root)
    contract_path = Path(contract_path)
    contract = json.loads(contract_path.read_text(encoding="utf-8"))
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list):
        raise ValueError("contract inputs must be a list")
    payloads = [load_payload(root / p) for p in inputs]
    return transform_component(payloads, contract)


def transform_component(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    name = contract.get("name")
    if not isinstance(name, str) or not name:
        raise ValueError("contract name must be a non-empty string")
    operation = contract.get("operation")
    if operation in ("integrity_evidence", "lag_evidence", "failure_evidence"):
        result = _evidence_result(payloads, contract)
    elif operation == "risk_ranking":
        result = _risk_result(payloads, contract)
    elif operation == "review_balance":
        result = _approval_result(payloads, contract)
    elif operation == "remediation_plan":
        result = _waves_result(payloads, contract)
    else:
        raise ValueError(f"unknown operation: {operation!r}")
    return {"name": name, "result": result}


def _require_field(rec, field):
    if field not in rec:
        raise ValueError(f"missing field {field}")
    return rec[field]


def _normalize_id(value):
    if not isinstance(value, str):
        raise ValueError("id must be a string")
    value = value.strip()
    if not value:
        raise ValueError("id must be non-empty after stripping")
    return value


def _normalize_revision(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("revision must be an integer")
    if value < 0:
        raise ValueError("revision must be >= 0")
    return value


def _normalize_owner(value):
    if not isinstance(value, str):
        raise ValueError("owner must be a string")
    value = value.strip().lower()
    if not value:
        raise ValueError("owner must be non-empty after stripping")
    return value


def _normalize_category(value):
    if not isinstance(value, str):
        raise ValueError("category must be a string")
    value = value.strip().lower()
    if value not in ("prepare", "copy", "verify"):
        raise ValueError("category must be prepare, copy, or verify")
    return value


def _normalize_tags(value):
    if not isinstance(value, list):
        raise ValueError("tags must be an array")
    tags = []
    for item in value:
        if not isinstance(item, str):
            raise ValueError("tags values must be strings")
        item = item.strip().lower()
        if not item:
            raise ValueError("tags values must be non-empty after stripping")
        tags.append(item)
    return sorted(set(tags))


def _normalize_nonneg_int(value, field):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{field} must be an integer")
    if value < 0:
        raise ValueError(f"{field} must be >= 0")
    return value


def _normalize_total(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError("total must be an integer")
    if value < 1:
        raise ValueError("total must be >= 1")
    return value


def _normalize_record(rec):
    if not isinstance(rec, dict):
        raise ValueError("record must be an object")
    nid = _normalize_id(_require_field(rec, "id"))
    revision = _normalize_revision(_require_field(rec, "revision"))
    owner = _normalize_owner(_require_field(rec, "owner"))
    category = _normalize_category(_require_field(rec, "category"))
    tags = _normalize_tags(_require_field(rec, "tags"))
    failures = _normalize_nonneg_int(_require_field(rec, "failures"), "failures")
    total = _normalize_total(_require_field(rec, "total"))
    lag = _normalize_nonneg_int(_require_field(rec, "lag"), "lag")
    valid = _require_field(rec, "valid")
    if not isinstance(valid, bool):
        raise ValueError("valid must be a boolean")
    if failures > total:
        raise ValueError("failures must not exceed total")
    return {
        "id": nid,
        "revision": revision,
        "owner": owner,
        "category": category,
        "tags": tags,
        "failures": failures,
        "total": total,
        "lag": lag,
        "valid": valid,
    }


def _dedupe_and_select(records):
    by_key = {}
    for rec in records:
        key = (rec["id"], rec["revision"])
        if key in by_key:
            if by_key[key] != rec:
                raise ValueError("conflicting records for the same (id, revision)")
        else:
            by_key[key] = rec
    best = {}
    for rec in by_key.values():
        current = best.get(rec["id"])
        if current is None or rec["revision"] > current["revision"]:
            best[rec["id"]] = rec
    return list(best.values())


def _contract_int(contract, field):
    value = contract.get(field)
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{field} must be an integer")
    return value


def _evidence_score(operation, rec, contract):
    offset = _contract_int(contract, "offset")
    if operation == "integrity_evidence":
        base = (0 if rec["valid"] else 15) + rec["failures"]
    elif operation == "lag_evidence":
        sla = contract.get("sla")
        if isinstance(sla, bool) or not isinstance(sla, (int, float)) or sla <= 0:
            raise ValueError("sla must be a positive number")
        base = math.ceil(rec["lag"] / sla)
    elif operation == "failure_evidence":
        base = math.ceil(20.0 * rec["failures"] / rec["total"])
    else:
        raise ValueError(f"unknown evidence operation: {operation!r}")
    score = base + offset
    return int(max(0, min(20, score)))


def _evidence_result(payloads, contract):
    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or len(inputs) != 1:
        raise ValueError("evidence components require exactly one input")
    if len(payloads) != 1:
        raise ValueError("evidence transform expects exactly one payload")
    payload = payloads[0]
    if not isinstance(payload, list):
        raise ValueError("evidence input must be a JSON array")
    normalized = [_normalize_record(rec) for rec in payload]
    selected = _dedupe_and_select(normalized)
    records = []
    for rec in selected:
        score = _evidence_score(contract["operation"], rec, contract)
        records.append({
            "id": rec["id"],
            "source": contract["name"],
            "owner": rec["owner"],
            "category": rec["category"],
            "tags": rec["tags"],
            "score": score,
        })
    records.sort(key=lambda r: (r["source"], r["id"]))
    return {
        "records": records,
        "count": len(records),
        "score_total": sum(r["score"] for r in records),
    }

