import heapq
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def discover_contracts():
    result = {}
    for path in ROOT.rglob("contract.json"):
        rel = path.relative_to(ROOT)
        if "outputs" in rel.parts:
            continue
        contract = json.loads(path.read_text(encoding="utf-8"))
        name = contract.get("name")
        if not isinstance(name, str) or not name:
            raise ValueError(f"contract missing name: {path}")
        if name in result:
            raise ValueError(f"duplicate component name: {name}")
        render = path.with_name("render.py")
        if not render.is_file():
            raise ValueError(f"missing render.py for component {name}")
        result[name] = {"contract": contract, "render": render}
    if not result:
        raise ValueError("no component contracts found")
    return result


def build_execution_order(components):
    by_output = {}
    for name, info in components.items():
        output = info["contract"].get("output")
        if not isinstance(output, str) or not output:
            raise ValueError(f"component {name} has invalid output")
        by_output[(ROOT / output).resolve()] = name

    deps = {}
    for name, info in components.items():
        inputs = info["contract"].get("inputs")
        if not isinstance(inputs, list):
            raise ValueError(f"component {name} has invalid inputs")
        dep_set = set()
        for inp in inputs:
            key = (ROOT / inp).resolve()
            if key in by_output and by_output[key] != name:
                dep_set.add(by_output[key])
        deps[name] = dep_set

    dependents = {name: [] for name in components}
    indeg = {}
    for name, ds in deps.items():
        indeg[name] = len(ds)
        for dep in ds:
            dependents[dep].append(name)

    ready = [n for n in components if indeg[n] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        name = heapq.heappop(ready)
        order.append(name)
        for dependent in sorted(set(dependents[name])):
            indeg[dependent] -= 1
            if indeg[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(components):
        raise ValueError("cyclic component dependencies")
    return order


def main():
    components = discover_contracts()
    order = build_execution_order(components)
    for name in order:
        render = components[name]["render"]
        subprocess.run([sys.executable, str(render)], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()

