def _waves_result(payloads, contract):
    merged = _merge_records(payloads)
    threshold = _contract_int(contract, "threshold")
    only_if_blocking = contract.get("only_if_blocking")
    if not isinstance(only_if_blocking, bool):
        raise ValueError("only_if_blocking must be a boolean")

    if only_if_blocking:
        has_blocker = any(
            "blocking" in r["tags"] and r["score"] >= threshold for r in merged
        )
        selected = merged if has_blocker else []
    else:
        selected = merged

